import { neonColors } from "../constants/color";
import { Card } from "../types";

export default function CardItem({ card }: { card: Card }) {
  const randomColor = neonColors[Math.floor(Math.random() * neonColors.length)];
  return (
    <div style={{ borderWidth: 2,borderStyle: "solid", borderColor: randomColor, padding: 8, marginBottom: 8, borderRadius: 4 }}>
      {card.title}
      {card.description && <p style={{ marginTop: 4, marginBottom: 0, fontSize: 14, color: "#666",  fontFamily: "Arial, sans-serif" }}>{card.description}</p>}
    </div>
  );
}
